import java.util.Scanner;

public class Demo {
    public static void main(String[] args) throws InterruptedException {
        // Activity 1: adding
        Scanner sc = new Scanner(System.in);
        System.out.println("Enter number 1");
        int num1 = sc.nextInt();
        System.out.println("Enter number 2");
        int num2 = sc.nextInt();
        System.out.println("Sum = " + (num1 + num2));
        System.out.println("Adding completed");

        // Activity 2: printing characters (5 seconds delay for each)
        System.out.println("Printing characters started");
        for (int i = 65; i <= 69; i++) {
            System.out.println((char) i);
            Thread.sleep(5000);
        }
        System.out.println("Printing characters completed");

        // Activity 3: printing numbers
        System.out.println("Printing numbers started");
        for (int i = 1; i <= 5; i++) {
            System.out.println(i);
        }
        System.out.println("Printing numbers completed");
    }
}

import java.util.Scanner;

class Adding extends Thread {
    public void run() {
        Scanner sc = new Scanner(System.in);
        System.out.println("Enter number 1");
        int num1 = sc.nextInt();
        System.out.println("Enter number 2");
        int num2 = sc.nextInt();
        System.out.println("Sum = " + (num1 + num2));
        System.out.println("Adding completed");
    }
}

class PrintingCharacters extends Thread {
    public void run() {
        System.out.println("Printing characters started");
        for (int i = 65; i <= 69; i++) {
            System.out.println((char) i);
            try {
                Thread.sleep(5000);
            } catch (InterruptedException e) {
                e.printStackTrace();
            }
        }
        System.out.println("Printing characters completed");
    }
}

class PrintingNumbers extends Thread {
    public void run() {
        System.out.println("Printing numbers started");
        for (int i = 1; i <= 5; i++) {
            System.out.println(i);
        }
        System.out.println("Printing numbers completed");
    }
}

public class Demo {
    public static void main(String[] args) {
        Adding a = new Adding();
        PrintingCharacters b = new PrintingCharacters();
        PrintingNumbers c = new PrintingNumbers();

        a.start();
        b.start();
        c.start();
    }
}

a.run();   // wrong: sequential, executes in the main stack
b.run();
c.run();

a.start(); // correct: a new small stack is created, run() executes there
b.start();
c.start();

